// Types of the Modern World map data (data/modern/, generated by tools/map) and its loader.
import type { TileLevel } from './tileMath';

export interface ProvinceData {
  id: number;
  key: string;
  name: string;
  owner: string;
  /** Label point in level-0 map pixels. */
  centroid: [number, number];
  areaKm2: number;
  neighbors: number[];
  isCoastal: boolean;
  /** Size on the level-0 map in pixels. */
  pixels: number;
  bbox: [number, number, number, number];
}

export interface CountryData {
  id: string;
  nameKey: string;
  status: 'full' | 'disputed' | 'uninhabited';
  capitalProvinceId: number;
  provinceIds: number[];
}

export interface CityData {
  id: number;
  name: string;
  provinceId: number;
  population: number;
  isCapital: boolean;
  isPort: boolean;
  /** Position in level-0 map pixels. */
  position: [number, number];
  /** Longitude and latitude in degrees. */
  lonLat: [number, number];
  generated?: boolean;
}

export interface ProvinceMapData {
  width: number;
  height: number;
  tileSize: number;
  levels: TileLevel[];
}

export interface MapData {
  provinces: ProvinceData[];
  countries: CountryData[];
  cities: CityData[];
  map: ProvinceMapData;
  /** Resolves a tile file from province-map.json to a URL. */
  tileUrl: (file: string) => string;
}

export async function loadMapData(onProgress: (fraction: number) => void): Promise<MapData> {
  const [provincesUrl, countriesUrl, citiesUrl, mapUrl, namesUrl] = await Promise.all([
    import('../../data/modern/provinces.json?url'),
    import('../../data/modern/countries.json?url'),
    import('../../data/modern/cities.json?url'),
    import('../../data/modern/map/province-map.json?url'),
    import('../../data/modern/province-names.json?url'),
  ]);
  const tiles = import.meta.glob<string>('../../data/modern/map/tiles/**/*.png', {
    query: '?url',
    import: 'default',
    eager: true,
  });

  let done = 0;
  const fetchJson = async <T>(url: string): Promise<T> => {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Failed to load ${url}: ${response.status}`);
    const json = (await response.json()) as T;
    onProgress(++done / 5);
    return json;
  };
  const [provinces, countries, cities, map, names] = await Promise.all([
    fetchJson<{ provinces: ProvinceData[] }>(provincesUrl.default),
    fetchJson<{ countries: CountryData[] }>(countriesUrl.default),
    fetchJson<{ cities: CityData[] }>(citiesUrl.default),
    fetchJson<ProvinceMapData>(mapUrl.default),
    fetchJson<{ renames: Record<string, string> }>(namesUrl.default),
  ]);
  // Current names for provinces whose source name is out of date.
  for (const p of provinces.provinces) p.name = names.renames[p.key] ?? p.name;

  return {
    provinces: provinces.provinces,
    countries: countries.countries,
    cities: cities.cities,
    map,
    tileUrl: (file) => {
      const url = tiles[`../../data/modern/map/${file}`];
      if (!url) throw new Error(`Unknown map tile ${file}`);
      return url;
    },
  };
}
